    const userResponse = await getProductLineOverviewByUserId(
      queryParamsData,
      headersData,
    );
    return formatResponse(200, userResponse);
  }

  const response = await getProductLineOverview(queryParamsData, headersData);

  return formatResponse(200, response);
});

export const main = middyfy(handler);

