import {
  getProductsByPn18,
  getProductsByProductCode,
  getProductsByUserId,
  getProductsByvin,
  logger,
  voucherProduct,
} from '@api-integration-aws/core/index';
import {formatResponse} from '@smart/feature-app/node';
import {ApiHandler} from 'sst/node/api';
import {middyfy} from '../../middleware/middy';
import {parseEvent} from '../../utils/parse-event';
import {ProductsHeadersSchema, ProductsRequestSchema} from './schema';

const handler = ApiHandler(async (event) => {
  const {queryParamsData, headersData} = parseEvent(event, {
    HeadersSchema: ProductsHeadersSchema,
    QueryParamsSchema: ProductsRequestSchema,
  });

  logger.info(`ECOM - Product - Query Params`, queryParamsData, headersData);

  const paramCount = [
    queryParamsData.voucherProductCode,
    queryParamsData.vin && queryParamsData.vin.length > 0,
    queryParamsData.productCode,
    queryParamsData.pn18,
  ].filter(Boolean).length;

  if (paramCount === 0) {
    throw new Error(
      `At least one parameter is required: voucherProductCode, vin, productCode, or pn18`,
    );
  }

  if (paramCount > 1) {
    throw new Error(
      `Only one parameter is allowed: voucherProductCode, vin, productCode, or pn18. Found ${paramCount} parameters.`,
    );
  }

  if (queryParamsData.voucherProductCode) {
    const response = await voucherProduct(queryParamsData, headersData);
    return formatResponse(200, response);
  }

  if (queryParamsData.vin && queryParamsData.vin.length > 0) {
    const response = await getProductsByvin(queryParamsData, headersData);
    return formatResponse(200, response);
  }
  if (queryParamsData.productCode && headersData[`user-id`]) {
    const response = await getProductsByUserId(queryParamsData, headersData);
    return formatResponse(200, response);
  }
  if (queryParamsData.productCode) {
    const response = await getProductsByProductCode(
      queryParamsData,
      headersData,
    );
    return formatResponse(200, response);
  }

  if (queryParamsData.pn18) {
    const response = await getProductsByPn18(queryParamsData, headersData);
    return formatResponse(200, response);
  }

  throw new Error(`Invalid request: No valid parameter found`);
});

export const main = middyfy(handler);

